pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }

    function testFuzz_property(address caller, uint256 amt) public {
        vm.assume(caller != address(0));

        c.mintToken(caller, 1);

        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(caller);

        bool ok;
        vm.prank(caller);
        try c.burn(amt) {
            ok = true;
        } catch {
            ok = false;
        }

        if (caller != address(this)) {
            assertTrue(c.totalSupply() == beforeTotal);
        } else {
            assertTrue(c.totalSupply() <= beforeTotal);
        }
    }
}
